begin;
do $$
declare p uuid; a uuid; b uuid; batch uuid; item_ids jsonb; line record; caught boolean;
begin
 p=public.warehouse_create_product(jsonb_build_object('sku','QA-LOC-'||gen_random_uuid(),'brand','SP','productNameCN','三库位优先级测试','boxMultiplier',10,'cartonMultiplier',100));
 perform public.warehouse_command('stock',jsonb_build_object('productId',p,'position',1,'location','Z-FIRST','kind','loose','unitsPerPack',1,'quantity',4,'mode','set'));
 perform public.warehouse_command('stock',jsonb_build_object('productId',p,'position',2,'location','A-SECOND','kind','box','unitsPerPack',10,'quantity',20,'mode','set'));
 perform public.warehouse_command('stock',jsonb_build_object('productId',p,'position',3,'location','M-THIRD','kind','loose','unitsPerPack',1,'quantity',6,'mode','set'));
 caught=false;
 begin perform public.warehouse_command('stock',jsonb_build_object('productId',p,'location','FOURTH','kind','loose','unitsPerPack',1,'quantity',1,'mode','set')); exception when others then caught=true; end;
 if not caught or (select count(distinct location) from public.inventory_bins where product_id=p and position is not null)<>3 then raise exception 'QA: fourth location was allowed'; end if;
 insert into public.orders(order_no,status,ai_status) values('QA-LOC-'||gen_random_uuid(),'uploaded','completed') returning id into a;
 perform public.warehouse_edit_item('add',jsonb_build_object('orderId',a,'productId',p,'qty',2,'unit','个'));
 perform public.warehouse_command('ready',jsonb_build_object('orderId',a));
 batch=(public.warehouse_command('create_batch',jsonb_build_object('orderIds',jsonb_build_array(a),'requestId',gen_random_uuid(),'name','QA priority','date',current_date))->>'id')::uuid;
 if (select count(*) from public.batch_lines where batch_id=batch)<>1 or (select location from public.batch_lines where batch_id=batch)<>'Z-FIRST' then raise exception 'QA: picking used name or box type instead of position'; end if;
 caught=false;
 begin perform public.warehouse_command('reorder_locations',jsonb_build_object('productId',p,'locations',jsonb_build_array('M-THIRD','Z-FIRST','A-SECOND'))); exception when others then caught=true; end;
 if not caught then raise exception 'QA: active batch locations reordered'; end if;
 select * into line from public.batch_lines where batch_id=batch;
 perform public.warehouse_command('pick',jsonb_build_object('lineId',line.id,'quantity',2));
 perform public.warehouse_command('start_packing',jsonb_build_object('batchId',batch));
 select jsonb_agg(id) into item_ids from public.order_items where order_id=a;
 perform public.warehouse_command('pack',jsonb_build_object('orderId',a,'checkedItemIds',item_ids));
 insert into public.orders(order_no,status,ai_status) values('QA-LOC-'||gen_random_uuid(),'uploaded','completed') returning id into a;
 perform public.warehouse_edit_item('add',jsonb_build_object('orderId',a,'productId',p,'qty',15,'unit','个'));
 perform public.warehouse_command('ready',jsonb_build_object('orderId',a));
 caught=false;
 begin perform public.warehouse_command('create_batch',jsonb_build_object('orderIds',jsonb_build_array(a),'requestId',gen_random_uuid(),'name','QA requires split','date',current_date)); exception when others then caught=true; end;
 if not caught or (select sum(reserved) from public.inventory_bins where product_id=p)<>0 then raise exception 'QA: skipped priority box location or leaked reservation'; end if;
 perform public.warehouse_command('review',jsonb_build_object('orderId',a));
 perform public.warehouse_edit_item('update',jsonb_build_object('itemId',(select id from public.order_items where order_id=a),'qty',17,'unit','个'));
 perform public.warehouse_command('ready',jsonb_build_object('orderId',a));
 insert into public.orders(order_no,status,ai_status) values('QA-LOC-'||gen_random_uuid(),'uploaded','completed') returning id into b;
 perform public.warehouse_edit_item('add',jsonb_build_object('orderId',b,'productId',p,'qty',5,'unit','个'));
 perform public.warehouse_command('ready',jsonb_build_object('orderId',b));
 perform public.warehouse_command('split_box',jsonb_build_object('binId',(select id from public.inventory_bins where product_id=p and kind='box'),'packs',1,'location','Z-FIRST'));
 batch=(public.warehouse_command('create_batch',jsonb_build_object('orderIds',jsonb_build_array(a,b),'requestId',gen_random_uuid(),'name','QA pick sequence','date',current_date))->>'id')::uuid;
 select * into line from public.batch_lines where batch_id=batch and position=2;
 caught=false;
 begin perform public.warehouse_command('pick',jsonb_build_object('lineId',line.id,'quantity',line.requested)); exception when others then caught=true; end;
 if not caught then raise exception 'QA: picked second location before first'; end if;
 for line in select * from public.batch_lines where batch_id=batch order by position loop
  perform public.warehouse_command('pick',jsonb_build_object('lineId',line.id,'quantity',line.requested));
 end loop;
 perform public.warehouse_command('start_packing',jsonb_build_object('batchId',batch));
 select jsonb_agg(id) into item_ids from public.order_items where order_id=a;
 perform public.warehouse_command('pack',jsonb_build_object('orderId',a,'checkedItemIds',item_ids));
 perform public.warehouse_command('close_batch',jsonb_build_object('batchId',batch));
 if (select sum(quantity) from public.inventory_bins where product_id=p)<>11 then raise exception 'QA: mixed box return lost units'; end if;
 if (select count(distinct location) from public.inventory_bins where product_id=p and position is not null)<>3 or (select position from public.inventory_bins where product_id=p and location='A-SECOND' and kind='loose')<>2 then raise exception 'QA: boxed return created fourth location'; end if;
 perform public.warehouse_command('reorder_locations',jsonb_build_object('productId',p,'locations',jsonb_build_array('M-THIRD','Z-FIRST','A-SECOND')));
 if (select min(position) from public.inventory_bins where product_id=p and location='M-THIRD')<>1 then raise exception 'QA: reorder failed'; end if;
 caught=false;
 begin perform public.warehouse_command('reorder_locations',jsonb_build_object('productId',p,'locations',jsonb_build_array('Z-FIRST','A-SECOND'))); exception when others then caught=true; end;
 if not caught then raise exception 'QA: removed nonempty location'; end if;
 perform public.warehouse_command('reorder_locations',jsonb_build_object('productId',p,'locations',jsonb_build_array('M-THIRD','A-SECOND')));
 perform public.warehouse_command('stock',jsonb_build_object('productId',p,'position',3,'location','B-NEW','kind','loose','unitsPerPack',1,'quantity',2,'mode','set'));
 if (select position from public.inventory_bins where product_id=p and location='Z-FIRST') is not null then raise exception 'QA: empty location not retired'; end if;
 if (select sum(quantity) from public.inventory_bins where product_id=p and position is not null)<>13 then raise exception 'QA: replacing empty location changed inventory'; end if;
 if (select quantity_on_hand from public.inventory where product_id=p)<>13 then raise exception 'QA: stock aggregate drift'; end if;
end $$;
set constraints all immediate;
rollback;
select 'PASS: max three locations, explicit priority, no skipped early boxes, enforced pick sequence, shared box/loose positions, returns, reordering and empty-position reuse' as result;
